  function codexHandle(msg){
    codexAuth.handleMessage(msg);assistantHub.observeCodex(msg);observeCodexTask(chat,msg);if(msg.method==='item/completed'){renderTaskPanel();scheduleSave()}

    if(msg.id!=null&&codexPending.has(msg.id)){let p=codexPending.get(msg.id);clearTimeout(p.t);codexPending.delete(msg.id);if(msg.error)p.reject(Error(msg.error.message||'Codex RPC error'));else p.resolve(msg.result);return}
    let m=msg.method,p=msg.params||{};
    if(m==='aiway/server'){if($('codexPersist'))$('codexPersist').textContent=p.persistence?(p.restored?'تم استعادة تسجيل الدخول المشفّر من Private Blob.':'التخزين المشفّر في Private Blob مفعّل.'):'التخزين الدائم غير مفعّل؛ أضف Private Blob و AIWAY_CREDENTIAL_KEY حتى يبقى تسجيل الدخول بعد cold start.';return}
    if(m==='aiway/error'){codexSetError(p.message||'خطأ من الخادم');return}
    if(m==='aiway/authPersistence'){if(p.enabled)$('codexPersist').textContent=p.saved?'تم حفظ تسجيل الدخول مشفّرًا.':'لم ينجح الحفظ الدائم؛ الحساب متاح في الجلسة الحالية فقط.';return}
    if(m==='aiway/codexExited'){codexSetError('توقفت عملية Codex على الخادم. أعد الاتصال.');return}
    else if(m==='account/updated'){codexLoadAccount(false)}
    else if(m==='account/rateLimits/updated'){codexRates=p.rateLimits||p;renderCodexUsage(codexRates)}
    else if(m==='item/agentMessage/delta'&&codexActiveOutput&&(!codexActiveTurnId||p.turnId===codexActiveTurnId)){codexActiveOutput.text+=(p.delta||'');processToolCalls(codexActiveOutput);if(chat?.messages?.at(-1)===codexActiveOutput)refreshLastMessage()}
    else if(m==='turn/completed'){let turn=p.turn||{},id=turn.id||p.turnId,w=codexTurnWaiters.get(id);if(w){codexTurnWaiters.delete(id);turn.status==='failed'?w.reject(Error(turn.error?.message||'فشل دور Codex')):w.resolve(turn)}}
    else if(m==='error'){let id=p.turnId,w=id&&codexTurnWaiters.get(id);if(w){codexTurnWaiters.delete(id);w.reject(Error(p.error?.message||p.message||'خطأ من Codex'))}}
  }
  async function codexConnect(){codexSetError('');try{await codexClient.connect();codexSocket=codexClient.socket;codexReady=codexClient.ready;await codexLoadAccount(false)}catch(error){codexReady=false;codexSetError(error.message)}}
