  function renderCodexAccount(){let a=codexAccountData,connected=a?.type==='chatgpt';$('codexAccount')?.classList.toggle('hidden',!connected);$('codexLogin')?.classList.toggle('hidden',connected);$('codexLogout')?.classList.toggle('hidden',!connected);$('codexRefresh')?.classList.toggle('hidden',!connected);$('codexUsage')?.classList.toggle('hidden',!connected);if(connected){let email=a.email||'حساب ChatGPT';$('codexEmail').textContent=email;$('codexPlan').textContent='ChatGPT '+planLabel(a.planType)+' · Codex';$('codexAvatar').textContent=(email[0]||'C').toUpperCase();codexSetStatus('متصل بالحساب','ok')}else if(codexReady&&!['connecting','waiting','verifying'].includes(codexAuth.state.phase))codexSetStatus('متصل · سجّل الدخول','warn')}
  function fmtReset(sec){if(!sec)return 'موعد إعادة التعيين غير متاح';try{return 'إعادة التعيين: '+new Date(sec*1000).toLocaleString('ar-EG',{dateStyle:'short',timeStyle:'short'})}catch{return '—'}}
  function chooseRateWindow(rates,targetMins){let snaps=[];if(rates?.rateLimits)snaps.push(rates.rateLimits);if(rates?.rateLimitsByLimitId)snaps.push(...Object.values(rates.rateLimitsByLimitId));let wins=[];for(let s of snaps)for(let w of [s?.primary,s?.secondary])if(w?.windowDurationMins)wins.push(w);if(!wins.length)return null;return wins.sort((a,b)=>Math.abs(a.windowDurationMins-targetMins)-Math.abs(b.windowDurationMins-targetMins))[0]}
  function renderCodexUsage(rates){let five=chooseRateWindow(rates,300),week=chooseRateWindow(rates,10080);for(let [w,pct,bar,reset] of [[five,'codex5Pct','codex5Bar','codex5Reset'],[week,'codexWeekPct','codexWeekBar','codexWeekReset']]){let used=Math.max(0,Math.min(100,Number(w?.usedPercent||0)));$(pct).textContent=w?used+'% مستخدم':'غير متاح';$(bar).style.width=w?used+'%':'0%';$(reset).textContent=w?fmtReset(w.resetsAt):'لم يُرجع Codex هذه النافذة'}}
