  async function codexSyncModels(){if(!codexReady||codexAccountData?.type!=='chatgpt')return[];let r=await codexRpc('model/list',{limit:100,includeHidden:false},30000),items=r?.data||[],models=items.map(x=>x.model||x.id).filter(Boolean),cp=providers.find(x=>x.type==='codex');if(cp){cp.models=[...new Set(models)];if(!cp.model){let d=items.find(x=>x.isDefault);cp.model=d?.model||cp.models[0]||''}persistConfig();if(provider()?.type==='codex'){modelLabel();renderModels()}}return models}
