  async function codexLogout(){await codexAuth.cancel();if(!codexReady)return;try{await codexRpc('account/logout',{});codexAccountData=null;codexRates=null;renderCodexAccount();$('codexUsage').classList.add('hidden');codexSetStatus('متصل · بدون حساب','warn');toast('تم تسجيل الخروج')}catch(error){codexSetError(error.message)}}
  function codexTurnPromise(id){return new Promise((resolve,reject)=>codexTurnWaiters.set(id,{resolve,reject}))}
  async function codexPushWorkspace(){if(!codexReady)return;await codexRpc('aiway/workspace/push',{files:chat.files||{}},30000)}
