  const {runCompatible,runGemini,runOpenCode}=createProviderRunners({get chat(){return chat},get controller(){return controller},get effort(){return effort},keyFor,commonMessages,effectiveSystem,TOOL_GUIDE,projectContext,isText,fileContext,processToolCalls,refreshLastMessage});
