  function renderHistory(){if(!chat)return;const all=[...chats.filter(x=>x.id!==chat.id),chat].sort((a,b)=>b.updated-a.updated);$('history').innerHTML=all.length?all.map(c=>`<div class="history-item ${c.id===chat.id?'selected':''}" data-chat="${esc(c.id)}"><i data-lucide="message-square" width="14"></i><span class="title">${esc(c.title)}</span><button class="delete" data-delete="${esc(c.id)}" title="حذف المحادثة"><i data-lucide="trash-2" width="13"></i></button></div>`).join(''):'<div class="empty-mini">مشروعاتك ستظهر هنا</div>';icons()}
