  function inline(s){return esc(s).replace(/`([^`\n]+)`/g,'<code>$1</code>').replace(/\*\*(.+?)\*\*/g,'<strong>$1</strong>').replace(/\[([^\]]+)\]\((https?:\/\/[^\s)]+)\)/g,(_,label,url)=>`<a href="${esc(url)}" target="_blank" rel="noopener noreferrer">${label}</a>`)}
  function markdown(text){const parts=String(text||'').split(/(```[^\n]*\n[\s\S]*?```)/g);return parts.map(part=>{if(part.startsWith('```')){let m=part.match(/^```([^\n]*)\n([\s\S]*?)```$/);if(!m)return inline(part);let label=m[1].trim()||'code',code=m[2];return `<div class="code-wrap"><div class="code-toolbar"><span>${esc(label)}</span><div><button data-copy-code="${encodeURIComponent(code)}">نسخ</button>${/\.(html|css|js|json|md|txt|svg)$/i.test(label)?`<button data-apply-code="${encodeURIComponent(label)}" data-code="${encodeURIComponent(code)}">إضافة للملفات</button>`:''}</div></div><pre><code>${esc(code)}</code></pre></div>`}return part.split('\n').map(line=>{if(/^###? /.test(line))return `<h3>${inline(line.replace(/^###? /,''))}</h3>`;if(/^# /.test(line))return `<h2>${inline(line.slice(2))}</h2>`;if(/^[-*] /.test(line))return `<div>• ${inline(line.slice(2))}</div>`;return line?`<div>${inline(line)}</div>`:'<br>'}).join('')}).join('')}
  function toolMeta(name){return ({create_file:{label:'جارٍ إنشاء الملف',icon:'file-plus-2'},write_file:{label:'جارٍ كتابة الملف',icon:'file-output'},edit_file:{label:'جارٍ تعديل الملف',icon:'file-pen-line'},read_file:{label:'جارٍ قراءة الملف',icon:'file-search'},delete_file:{label:'جارٍ حذف الملف',icon:'trash-2'},list_files:{label:'جارٍ قراءة قائمة الملفات',icon:'files'},preview:{label:'جارٍ تجهيز المعاينة',icon:'monitor-play'}})[name]||{label:'جارٍ تنفيذ أداة',icon:'loader-circle'}}
  function pendingTool(text){let raw=String(text||''),start=raw.lastIndexOf('```aiway-tool');if(start<0)return null;let tail=raw.slice(start+15);if(tail.includes('```'))return null;let name=(tail.match(/"name"\s*:\s*"([^"]+)/)||[])[1]||'';let path=(tail.match(/"path"\s*:\s*"([^"]+)/)||[])[1]||'';if(!name&&!tail.trim())return{name:'tool',path:''};return{name:name||'tool',path}}
