  async function send(){if(busy){stopGeneration();return}if(pendingChanges){toast('اقبل أو ارفض التعديلات المعلقة قبل طلب جديد');setTab('diff');return}let text=$('prompt').value.trim();if(!text&&!attached.length)return;let p=chooseProviderFor(text);if(p.type!=='codex'&&!p?.model){toast('اختر نموذجاً من الإعدادات أولاً');openSettings();return}if(!['opencode','compatible','codex'].includes(p.type)&&!keyFor(p)){toast(p.type==='gemini'?'أضف مفتاح Gemini API':'أضف مفتاح API للمتابعة');openSettings();return}if(!['gemini'].includes(p.type)&&attached.some(f=>f.mime==='application/pdf')){toast('ملفات PDF المباشرة مدعومة مع Gemini فقط حالياً.');return}let files=attached.splice(0);let user={id:uid(),role:'user',text,attachments:files,files:files.map(f=>({name:f.name})),time:Date.now()};try{user.context=assistantHub.references(text).context;turnHubContext=assistantHub.systemContext()}catch(error){attached.push(...files);renderAttachments();toast(error.message);return}assistantHub.hideReferences();chat.messages.push(user);if(chat.messages.length===1)chat.title=(text||files[0]?.name||'مشروع جديد').slice(0,36);$('prompt').value='';$('prompt').style.height='auto';renderAttachments();let answer={id:uid(),role:'assistant',text:'',reason:'',time:Date.now(),loading:true,providerName:p.name};chat.messages.push(answer);renderChat();startTask(chat,text||'مهمة من المرفقات');renderTaskPanel();setBusy(true);controller=new AbortController();const currentChat=chat;try{let backup=assistantHub.backupProvider();if(chat.messages.some(m=>m.attachments?.some(f=>f.mime==='application/pdf'))&&backup?.type!=='gemini')backup=null;await runWithFallback({primary:p,backup,output:answer,signal:controller.signal,run:async target=>{if(target.type==='codex')await runCodex(target,chat.messages.slice(0,-1),answer);else if(target.type==='gemini')await runGemini(target,chat.messages.slice(0,-1),answer);else if(target.type==='opencode')await runOpenCode(target,chat.messages.slice(0,-1),answer);else await runCompatible(target,chat.messages.slice(0,-1),answer)},onFallback:(primary,target,error)=>{answer.providerName=target.name;answer.toolEvents=[...(answer.toolEvents||[]),'المزود الاحتياطي: '+primary.name+' → '+target.name];logTool('provider_fallback',target.name,'ok',error.message);toast('تعذر المزود الأساسي؛ جارٍ استخدام '+target.name);refreshLastMessage(true)}});if(!answer.text&&!answer.reason)answer.error='لم يرجع النموذج محتوى. جرّب نموذجاً آخر.'}catch(e){if(e.name!=='AbortError')answer.error=(e instanceof TypeError?'تعذر الاتصال. تحقق من الاتصال وإعدادات المزود.':e.message)}finally{if(currentChat===chat)processToolCalls(answer);answer.loading=false;if(currentChat===chat){refreshLastMessage(true);saveChat()}else if(db){let req=store('readwrite').put(structuredClone(currentChat));req.onerror=()=>toast('تعذر حفظ المحادثة')}if(db)chats=await allChats();if(currentChat.task){currentChat.task.running=false;currentChat.task.phase=pendingChanges?'review':currentChat.task.checks?'tests':'context'}renderTaskPanel();setBusy(false);saveChat();controller=null}}
  function openSettings(){$('settingsModal').classList.remove('hidden');fillProviderSelect();fillProvider(activeId);$('sidebar').classList.remove('mobile-open');closePopovers()}
  function closeSettings(){$('settingsModal').classList.add('hidden')}
  function fillProviderSelect(){let selected=$('providerSelect').value||activeId;$('providerSelect').innerHTML=providers.map(p=>`<option value="${esc(p.id)}">${esc(p.name)}</option>`).join('');$('providerSelect').value=providers.some(p=>p.id===selected)?selected:activeId}
  function fillProvider(id){let p=providers.find(x=>x.id===id);if(!p)return;let isCodex=p.type==='codex';$('providerSelect').value=id;$('providerName').value=p.name;$('providerType').value=p.type;$('providerUrl').value=p.url;$('providerUrl').disabled=isCodex;$('providerModel').value=p.model;$('providerKey').value=isCodex?'':keyFor(p);$('providerKey').disabled=isCodex;$('rememberKey').checked=!isCodex&&!!p.remember;$('rememberKey').disabled=isCodex;$('systemPrompt').value=systemPrompt;$('modelCount').textContent=p.models?.length?`${p.models.length} نموذج متاح`:'';$('modelOptions').innerHTML=(p.models||[]).map(m=>`<option value="${esc(m)}"></option>`).join('')}
  function settingsDraft(){return{id:$('providerSelect').value,name:$('providerName').value.trim()||'مزود جديد',type:$('providerType').value,url:$('providerUrl').value.trim().replace(/\/+$/,''),model:$('providerModel').value.trim(),key:$('providerKey').value.trim(),remember:$('rememberKey').checked}}
  function saveSettings(){let draft=settingsDraft();if(draft.type!=='codex'&&!/^https?:\/\//i.test(draft.url)){toast('اكتب رابط URL صحيح يبدأ بـ http أو https');return}let p=providers.find(x=>x.id===draft.id);Object.assign(p,{name:draft.name,type:draft.type,url:draft.url,model:draft.model,remember:draft.remember});localStorage.removeItem('aiway.key.'+p.id);sessionStorage.removeItem('aiway.key.'+p.id);if(draft.key)(draft.remember?localStorage:sessionStorage).setItem('aiway.key.'+p.id,draft.key);activeId=p.id;systemPrompt=$('systemPrompt').value.trim()||DEFAULT_SYSTEM;persistConfig();modelLabel();closeSettings();toast('تم حفظ الإعدادات')}
  async function fetchModels(){let d=settingsDraft(),btn=$('fetchModels');if(d.type!=='codex'&&!/^https?:\/\//i.test(d.url)){toast('أدخل رابط المزود أولاً');return}btn.disabled=true;btn.textContent='جارٍ جلب النماذج...';try{let models=[];if(d.type==='codex'){if(!codexReady)await codexConnect();if(codexAccountData?.type!=='chatgpt')throw Error('سجّل الدخول بحساب ChatGPT أولاً');models=await codexSyncModels()}else{let url,headers={};if(d.type==='gemini'){if(!d.key)throw Error('أضف Gemini API Key');url=d.url+'/models';headers['x-goog-api-key']=d.key}else if(d.type==='opencode'){url=d.url+'/config/providers';if(d.key)headers.Authorization='Basic '+btoa('opencode:'+d.key)}else{url=d.url+'/models';if(d.key)headers.Authorization='Bearer '+d.key}let res=await fetch(url,{headers});if(!res.ok)throw Error('HTTP '+res.status+': '+(await res.text()).slice(0,130));let data=await res.json();if(d.type==='gemini')models=(data.models||[]).filter(x=>!x.supportedGenerationMethods||x.supportedGenerationMethods.includes('generateContent')).map(x=>x.name.replace(/^models\//,''));else if(d.type==='opencode')models=(data.providers||[]).flatMap(x=>Object.keys(x.models||{}).map(m=>x.id+'/'+m));else models=(data.data||data.models||[]).map(x=>typeof x==='string'?x:x.id).filter(Boolean);models=[...new Set(models)].sort()}if(!models.length)throw Error('لم يتم العثور على نماذج');let p=providers.find(x=>x.id===d.id);p.models=models;$('modelOptions').innerHTML=models.map(m=>`<option value="${esc(m)}"></option>`).join('');$('modelCount').textContent=models.length+' نموذج متاح';if(!d.model)$('providerModel').value=models[0];persistConfig();renderModels();toast(`تم جلب ${models.length} نموذج.`)}catch(e){toast('تعذر جلب النماذج: '+e.message)}finally{btn.disabled=false;btn.innerHTML='<i data-lucide="refresh-cw" width="14" style="display:inline;vertical-align:middle"></i> جلب النماذج من المزود';icons()}}
  function toggleWorkspace(show){$('workspace').classList.toggle('hidden',!show);$('workspaceToggle').classList.toggle('on',show);$('sidebar').classList.remove('mobile-open');if(show)renderFiles();if(!show)document.body.classList.remove('split-preview')}
  function renderFiles(){if(!chat)return;let names=Object.keys(chat.files||{}),term=($('fileSearch')?.value||'').toLowerCase();if(selectedFile&&!names.includes(selectedFile))selectedFile=null;if(!selectedFile&&names.length)selectedFile=names[0];if(selectedFile&&!openFiles.includes(selectedFile))openFiles.push(selectedFile);openFiles=openFiles.filter(n=>names.includes(n)).slice(-8);let shown=(term?names.filter(n=>n.toLowerCase().includes(term)):names).sort();$('fileList').innerHTML=shown.length?shown.map((name,i)=>{const folder=name.includes('/')?name.slice(0,name.lastIndexOf('/')):'المجلد الرئيسي',previous=i?(shown[i-1].includes('/')?shown[i-1].slice(0,shown[i-1].lastIndexOf('/')):'المجلد الرئيسي'):null;return (folder!==previous?'<div class="folder-heading">▾ '+esc(folder)+'</div>':'')+`<button class="file-row ${name===selectedFile?'active':''}" data-file="${esc(name)}"><i data-lucide="${name.endsWith('.html')?'file-code-2':name.endsWith('.css')?'palette':'file-code'}" width="14"></i><span>${esc(name)}</span><span class="remove-file" data-remove-file="${esc(name)}"><i data-lucide="x" width="13"></i></span></button>`}).join(''):'<div class="empty-mini">لا توجد ملفات مطابقة.</div>';$('openFileTabs').innerHTML=openFiles.map(n=>`<button class="open-tab ${n===selectedFile?'active':''}" data-file="${esc(n)}">${esc(n)}</button>`).join('');$('editingName').textContent=selectedFile||'لا يوجد ملف محدد';$('codeEditor').value=selectedFile?chat.files[selectedFile]:'';$('codeEditor').disabled=!selectedFile;editor.show(chat.id,selectedFile,selectedFile?chat.files[selectedFile]:'');$('statusFile').textContent=selectedFile||'No file';icons()}
  function setTab(tab){if(tab!=="files"&&tab!=="preview")document.body.classList.remove("split-preview");wsTab=tab;document.querySelectorAll('.ws-tabs button').forEach(b=>b.classList.toggle('active',b.dataset.tab===tab));for(let name of ['files','preview','task','diff','versions','terminal','github','tools','assistant'])$(name+'Tab')?.classList.toggle('hidden',tab!==name);if(tab==='assistant')assistantHub.refresh();if(tab==='task')renderTaskPanel();if(tab==='preview')renderPreview();if(tab==='diff')renderDiff();if(tab==='versions')renderVersions();if(tab==='github')renderGithub();if(tab==='tools')renderToolLog()}
