  function snapshotProject(label='نقطة استعادة'){if(!chat)return;chat.versions ||= [];let files=structuredClone(chat.files||{}),last=chat.versions.at(-1);if(last&&filesEqual(last.files,files))return;chat.versions.push({id:uid(),time:Date.now(),label,files});if(chat.versions.length>25)chat.versions=chat.versions.slice(-25);scheduleSave();if(wsTab==='versions')renderVersions()}
