  async function init(){icons();modelLabel();setupEnhancements();assistantHub.mount();setupTaskFeatures();try{db=await openDB();chats=await allChats();const id=localStorage.getItem('aiway.lastProject'),saved=chats.find(c=>c.id===id)||[...chats].sort((a,b)=>b.updated-a.updated)[0];if(saved){chat=saved;pendingChanges=chat.pendingChanges||null;selectedFile=chat.selectedFile||null;for(const m of chat.messages||[])if(m.loading){m.loading=false;m.error='توقفت المهمة عند إغلاق الصفحة؛ الرد الجزئي محفوظ'}renderAttachments();renderChat();renderFiles();renderHistory();renderDiff()}else newChat()}catch(e){toast('تعذر تشغيل التخزين المحلي');newChat()}featureModeUI();renderGithub();setTimeout(()=>codexConnect().catch(()=>{}),250)}

  function scheduleReconnect(){codexClient.scheduleRetry()}
  async function confirmGithubPush(){
    const btn=$('githubReviewConfirm'),review=githubReview;
    if(!review||btn.disabled)return;
    if(review.changes.some(c=>c.kind==='delete')&&!$('githubDeleteConfirm').checked){toast('وافق على الحذف الصريح قبل الرفع');return}
    btn.disabled=true;
    try {
      saveGithubPrefs();const g=chat.github;
      if(review.projectId!==chat.id||review.repo!==g.repo||review.branch!==g.branch||!filesEqual(review.files,chat.files))throw Error('المشروع تغيّر بعد المراجعة؛ افتح المراجعة مجددًا');
      const ref=await githubFetch('/repos/'+g.repo+'/git/ref/heads/'+encodeURIComponent(g.branch));
      if(ref.object.sha!==review.sha)throw Error('الفرع تغيّر على GitHub. اسحب آخر نسخة قبل الرفع؛ نزّل ZIP لحفظ تعديلاتك أولًا.');
      const parent=await githubFetch('/repos/'+g.repo+'/git/commits/'+review.sha),items=[];
      for(const change of review.changes){
        if(change.kind==='delete'){items.push({path:change.path,mode:g.modes?.[change.path]||'100644',type:'blob',sha:null});continue}
        const bytes=new TextEncoder().encode(change.content);let binary='';
        for(let i=0;i<bytes.length;i+=8192)binary+=String.fromCharCode(...bytes.subarray(i,i+8192));
        const blob=await githubFetch('/repos/'+g.repo+'/git/blobs',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({encoding:'base64',content:btoa(binary)})});
        items.push({path:change.path,mode:g.modes?.[change.path]||'100644',type:'blob',sha:blob.sha});
      }
      const tree=await githubFetch('/repos/'+g.repo+'/git/trees',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({base_tree:parent.tree.sha,tree:items})});
      const commit=await githubFetch('/repos/'+g.repo+'/git/commits',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({message:$('githubCommit').value.trim()||'Update from AiWay',tree:tree.sha,parents:[review.sha]})});
      await githubFetch('/repos/'+g.repo+'/git/refs/heads/'+encodeURIComponent(g.branch),{method:'PATCH',headers:{'Content-Type':'application/json'},body:JSON.stringify({sha:commit.sha,force:false})});
      g.baseSha=commit.sha;g.baseFiles=structuredClone(review.files);saveChat();$('githubStatus').textContent='تم رفع '+review.changes.length+' ملف · '+commit.sha.slice(0,7);$('githubReviewModal').classList.add('hidden');toast('تم الرفع إلى GitHub');
    }catch(e){toast(e.message);$('githubStatus').textContent=e.message}finally{btn.disabled=false}
  }
  function downloadBlob(name,blob){const url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),10000)}
  async function exportProject(){try{downloadBlob((chat.title.replace(/[<>:"/\\|?*]/g,'_')||'aiway-project')+'.zip',await exportZip(chat.files||{}));toast('تم تصدير ملفات المشروع')}catch(e){toast(e.message)}}
  async function importProject(e){
    try {
      let imported=Object.create(null),total=0;
      for(const file of e.target.files){
        if(file.name.endsWith('.zip')){
          let zipFiles=await importZip(file),names=Object.keys(zipFiles),first=names[0]?.split('/')[0];
          if(first&&names.every(n=>n.startsWith(first+'/'))&&(Object.hasOwn(zipFiles,first+'/index.html')||Object.hasOwn(zipFiles,first+'/package.json')))zipFiles=Object.fromEntries(names.map(n=>[n.slice(first.length+1),zipFiles[n]]));
          Object.assign(imported,zipFiles);
        }else{if(file.size>2*1024*1024)throw Error('الملف أكبر من 2MB');const bytes=new Uint8Array(await file.arrayBuffer());if(bytes.includes(0))throw Error('ملف ثنائي غير مدعوم: '+file.name);imported[safePath(file.webkitRelativePath||file.name)]=new TextDecoder('utf-8',{fatal:true}).decode(bytes)}
      }
      const next={...chat.files,...imported};for(const content of Object.values(next))total+=new TextEncoder().encode(content).length;
      if(Object.keys(next).length>200||total>12*1024*1024)throw Error('المشروع يتجاوز 200 ملف أو 12MB');
      if(pendingChanges)throw Error('راجع تعديلات AI قبل استيراد ملفات');
      snapshotProject('قبل الاستيراد');chat.files=next;selectedFile=Object.keys(imported)[0]||selectedFile;renderFiles();saveChat();schedulePreview();toast('تم استيراد '+Object.keys(imported).length+' ملف');
    }catch(error){toast(error.message)}finally{e.target.value=''}
  }
  async function backupProjects(){
    saveChat();const projects=db?await allChats():[chat];
    // Provider keys, GitHub tokens and server authentication are not part of backups.
    const payload={format:'aiway-backup',version:1,created:new Date().toISOString(),projects};
    downloadBlob('aiway-backup-'+new Date().toISOString().slice(0,10)+'.json',new Blob([JSON.stringify(payload,null,2)],{type:'application/json'}));
  }
  async function restoreBackup(e){
    try {
      const file=e.target.files[0];if(!file)return;if(file.size>40*1024*1024)throw Error('النسخة أكبر من 40MB');
      const payload=JSON.parse(await file.text());if(payload.format!=='aiway-backup'||payload.version!==1||!Array.isArray(payload.projects)||payload.projects.length>100)throw Error('نسخة احتياطية غير صالحة');
      const restored=payload.projects.map(project=>{
        if(typeof project.title!=='string'||!Array.isArray(project.messages)||!project.files||typeof project.files!=='object'||Array.isArray(project.files))throw Error('بيانات مشروع غير صالحة');
        const files=Object.create(null);let total=0;
        for(const [path,text] of Object.entries(project.files)){if(typeof text!=='string')throw Error('محتوى ملف غير صالح');const size=new TextEncoder().encode(text).length;total+=size;if(size>2*1024*1024||total>12*1024*1024)throw Error('المشروع أكبر من الحد المسموح');files[safePath(path)]=text}
        if(Object.keys(files).length>200)throw Error('ملفات كثيرة في النسخة');
        return {id:uid(),title:project.title.slice(0,80)+' — مستعاد',messages:project.messages,files,versions:[],github:{},assistant:normalizeAssistantState(project.assistant),created:Date.now(),updated:Date.now()};
      });
      const tx=db.transaction('chats','readwrite');for(const project of restored)tx.objectStore('chats').put(project);
      await new Promise((resolve,reject)=>{tx.oncomplete=resolve;tx.onerror=()=>reject(tx.error)});chats=await allChats();renderHistory();toast('تمت استعادة '+restored.length+' مشروع كنسخ مستقلة');
    }catch(error){toast(error.message)}finally{e.target.value=''}
  }
  function setupEnhancements(){
    const dark=localStorage.getItem('aiway.theme')==='dark';document.documentElement.dataset.theme=dark?'dark':'light';editor.theme(dark);
    $('themeToggle').onclick=()=>{const dark=document.documentElement.dataset.theme!=='dark';document.documentElement.dataset.theme=dark?'dark':'light';localStorage.setItem('aiway.theme',dark?'dark':'light');editor.theme(dark)};
    $('githubReviewConfirm').onclick=confirmGithubPush;
    $('githubReviewCancel').onclick=()=>{$('githubReviewModal').classList.add('hidden');githubReview=null};
    $('githubPush').addEventListener('click',()=>{$('githubDeleteConfirm').checked=false});
    $('backupExport').onclick=()=>backupProjects().catch(e=>toast(e.message));$('backupImport').onclick=()=>$('backupInput').click();$('backupInput').onchange=restoreBackup;
    $('refreshPreview').onclick=renderPreview;
    $('previewSize').onchange=()=>{$('previewFrame').style.width=$('previewSize').value};
    $('fullscreenPreview').onclick=()=>{const el=$('previewTab');if(document.fullscreenElement)document.exitFullscreen();else el.requestFullscreen().catch(e=>toast(e.message))};
    $('wideWorkspace').onclick=()=>{document.body.classList.toggle('wide-workspace')};
    $('splitPreview').onclick=()=>{toggleWorkspace(true);setTab('files');document.body.classList.toggle('split-preview');if(document.body.classList.contains('split-preview'))renderPreview()};
    const workspace=$('workspace'),resize=$('workspaceResize');
    const setWidth=width=>{const value=Math.max(340,Math.min(innerWidth-260,width));workspace.style.width=value+'px';localStorage.setItem('aiway.workspaceWidth',String(value))};
    const remembered=Number(localStorage.getItem('aiway.workspaceWidth'));if(remembered&&innerWidth>800)setWidth(remembered);
    resize.onpointerdown=e=>{if(innerWidth<=800||document.body.classList.contains('wide-workspace'))return;resize.setPointerCapture(e.pointerId);const start=e.clientX,width=workspace.getBoundingClientRect().width;const move=event=>setWidth(width+event.clientX-start),end=()=>{resize.removeEventListener('pointermove',move);resize.removeEventListener('pointerup',end);resize.removeEventListener('pointercancel',end)};resize.addEventListener('pointermove',move);resize.addEventListener('pointerup',end);resize.addEventListener('pointercancel',end)};
    resize.onkeydown=e=>{if(['ArrowLeft','ArrowRight'].includes(e.key)){e.preventDefault();setWidth(workspace.getBoundingClientRect().width+(e.key==='ArrowRight'?30:-30))}};
    window.addEventListener('online',()=>{codexClient.retryAttempt=0;scheduleReconnect()});
    window.addEventListener('offline',()=>{clearTimeout(codexClient.retryTimer);codexClient.retryTimer=null;codexSetStatus('لا يوجد اتصال بالإنترنت','warn')});
    window.addEventListener('pagehide',()=>{if(chat&&db)saveChat()});
    document.addEventListener('keydown',e=>{if(e.key==='Escape')$('githubReviewModal').classList.add('hidden')});
  }

  function renderTaskPanel(){renderTask($('taskContent'),chat?.task,{language:uiLanguage,pending:Boolean(pendingChanges),busy});const button=$('runTaskTests');if(button)button.onclick=runProjectTests}
  async function runProjectTests({allowBusy=false}={}){
    if(!chat||(busy&&!allowBusy)||chat.task?.checks?.status==='running')return;const project=chat,files=structuredClone(pendingChanges?.files||chat.files||{});
    if(!project.task)startTask(project,'التحقق من المشروع');
    const taskId=project.task.id;project.task.checks={status:'running',summary:'جارٍ تشغيل الاختبارات داخل عامل معزول…',results:[]};addTaskEvent(project,'tests','بدأ فحص ملفات '+(pendingChanges?'التعديلات المقترحة':'المشروع'));renderTaskPanel();
    try{const result=await runWorkspaceTests(files);if(project.task?.id!==taskId)return;project.task.checks=result;addTaskEvent(project,'tests',result.summary)}
    catch(error){project.task.checks={status:'failed',summary:error.message,results:[]};addTaskEvent(project,'tests',error.message)}
    if(project===chat){if(!filesEqual(files,pendingChanges?.files||chat.files)){project.task.checks.summary+=' · الملفات تغيّرت بعد بدء الفحص؛ أعد التحقق';project.task.checks.status='stale'}project.task.phase=pendingChanges?'review':'tests';renderTaskPanel();saveChat()}
    else if(db)store('readwrite').put(structuredClone(project));
  }
  function updateLoginUI(state){
    const pending=['connecting','waiting','verifying'].includes(state.phase);
    $('codexLogin').disabled=pending;$('codexLogin').textContent=pending?'جارٍ تسجيل الدخول…':'تسجيل الدخول بحساب ChatGPT';
    $('codexCancelLogin').classList.toggle('hidden',!pending);$('codexDevice').classList.toggle('hidden',state.phase!=='waiting');
    if(state.phase==='waiting'){$('codexUserCode').textContent=state.code;codexVerifyUrl=state.url;$('codexLoginProgress').textContent='أدخل الكود في صفحة OpenAI · متبقي '+state.remaining+' ثانية'+(state.popupBlocked?' · افتح الرابط يدويًا من الزر أدناه':'');codexSetStatus('بانتظار موافقتك','warn')}
    else $('codexLoginProgress').textContent=state.phase==='connecting'?'تجهيز الاتصال وطلب كود الدخول…':state.phase==='verifying'?'جارٍ التحقق من الحساب…':state.phase==='authenticated'?'تم ربط الحساب':state.phase==='cancelled'?'تم إلغاء المحاولة':'';
    if(state.error)codexSetError(state.error);else if(['connecting','authenticated','cancelled'].includes(state.phase))codexSetError('');
    if(['error','expired'].includes(state.phase))codexSetStatus('تسجيل الدخول يحتاج محاولة جديدة','warn');
  }
  function connectionState(phase,message){
    $('codexConnectionDetail').textContent=message;
    codexSetStatus(message,phase==='ready'?'ok':phase==='error'?'warn':'');
    if(phase==='error')codexSetError(message);else if(phase==='ready'&&!['error','expired'].includes(codexAuth.state.phase))codexSetError('');
  }
  const codexClient=new CodexClient({
    onMessage:codexHandle,onState:connectionState,
    onReady:()=>{codexSocket=codexClient.socket;codexReady=true;codexConnectionId++;codexLoadAccount(false)},
    onDisconnect:()=>{codexReady=false;codexAuth.handleDisconnect();for(const [id,waiter] of codexTurnWaiters){waiter.reject(Error('انقطع اتصال Codex؛ الرد الجزئي محفوظ'));codexTurnWaiters.delete(id)}if(codexActiveOutput){codexActiveOutput.error='انقطع اتصال Codex؛ الرد الجزئي محفوظ';saveChat()}}
  });
  const codexAuth=new CodexLogin(codexClient,{onState:updateLoginUI,onAccount:account=>{codexAccountData=account;renderCodexAccount();Promise.allSettled([codexRefreshUsage(),codexSyncModels()]);toast('تم ربط حساب ChatGPT')}});
  let uiLanguage=localStorage.getItem('aiway.language')==='en'?'en':'ar';
  function updateLanguage(){
    const en=uiLanguage==='en';document.documentElement.lang=uiLanguage;document.documentElement.dir=en?'ltr':'rtl';$('languageToggle').textContent=en?'العربية':'English';
    for(const [id,ar,english] of [['newChat','مشروع جديد','New project'],['sidebarWorkspace','مساحة العمل','Workspace'],['sidebarSettings','الإعدادات والمزودون','Settings & providers'],['backupExport','تنزيل نسخة احتياطية','Download backup'],['backupImport','استعادة نسخة احتياطية','Restore backup']]){const button=$(id);if(button){const text=[...button.childNodes].find(n=>n.nodeType===Node.TEXT_NODE&&n.textContent.trim());if(text)text.textContent=' '+(en?english:ar);else button.textContent=en?english:ar}}
    for(const [tab,ar,english] of [['files','الملفات','Files'],['preview','المعاينة','Preview'],['task','المهمة','Task'],['diff','الفروق','Changes'],['versions','الإصدارات','History'],['terminal','Terminal','Terminal'],['github','GitHub','GitHub'],['tools','السياق','Context'],['assistant','الوكيل','Assistant']]){const button=document.querySelector('[data-tab="'+tab+'"]');if(button)button.textContent=en?english:ar}
    $('prompt').placeholder=en?'Describe your coding task…':'اكتب مهمتك بالعربية…';
    $('taskTemplates').innerHTML=taskTemplates.map(t=>'<button class="task-template" data-task-template="'+t.id+'"><strong>'+(en?t.en:t.ar)+'</strong><span>'+(en?'Context → changes → checks → review':'سياق ← تعديل ← اختبار ← مراجعة')+'</span></button>').join('');
    renderTaskPanel();localStorage.setItem('aiway.language',uiLanguage);
  }
  function setupTaskFeatures(){
    $('codexCancelLogin').onclick=()=>codexAuth.cancel();$('codexCheckAccount').onclick=()=>codexLoadAccount(false);
    $('codexDiagnose').onclick=async()=>{try{const response=await fetch('/api/ws',{cache:'no-store'});$('codexConnectionDetail').textContent=response.status===426?'مسار /api/ws موجود. إذا لم يفتح WebSocket، راجع إعدادات الاستضافة وسجل الخادم.':response.ok?'مسار Codex متاح':'مسار Codex غير متاح (HTTP '+response.status+')'}catch(error){$('codexConnectionDetail').textContent=error.message}};
    $('languageToggle').onclick=()=>{uiLanguage=uiLanguage==='ar'?'en':'ar';updateLanguage()};
    $('runReviewTests').onclick=()=>{toggleWorkspace(true);setTab('task');runProjectTests()};
    document.addEventListener('click',event=>{const button=event.target.closest('[data-task-template]');if(!button)return;const template=taskTemplates.find(t=>t.id===button.dataset.taskTemplate);$('prompt').value=template.prompt;agentMode=true;persistConfig();featureModeUI();$('prompt').focus()});
    updateLanguage();
  }

  const assistantHub=createAssistantHub({getChat:()=>chat,getProjects:()=>[...chats.filter(p=>p.id!==chat?.id),...(chat?[chat]:[])],getFiles:()=>chat?.files||{},getPending:()=>pendingChanges?.files,getProviders:()=>providers,getBusy:()=>busy,allowProjectFiles:()=>!$('ctxProject')||$('ctxProject').checked,save:saveChat,loadChat,toast,download:downloadBlob,cleanText:visibleAssistantText,open:()=>{toggleWorkspace(true);setTab('assistant')}});
init();
